unicorn_colossus.source:
export const envelope = [24, 38, 24];

export default function build(api) {
  const [W, H, D] = api.size;

  // Palette resolution from theme with radiant celestial fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:quartz_pillar";
  const plinthBlock = api.theme?.ground?.plinth || "minecraft:quartz_bricks";
  const revetmentBlock = api.theme?.ground?.revetment || "minecraft:diorite";
  const chiseledQuartz = "minecraft:chiseled_quartz_block";
  const goldBlock = "minecraft:gold_block";
  const seaLantern = "minecraft:sea_lantern";
  const amethyst = "minecraft:amethyst_block";

  // Voxel storage: deterministic flat grid [W, H, D]
  const voxels = new Array(W * H * D).fill(null);

  function getIdx(x, y, z) {
    return (x * H + y) * D + z;
  }

  function setVoxel(x, y, z, block) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      voxels[getIdx(ix, iy, iz)] = block;
    }
  }

  function drawSphere(cx, cy, cz, r, block) {
    const ri = Math.ceil(r);
    const r2 = r * r;
    for (let x = Math.floor(cx - ri); x <= Math.ceil(cx + ri); x++) {
      for (let y = Math.floor(cy - ri); y <= Math.ceil(cy + ri); y++) {
        for (let z = Math.floor(cz - ri); z <= Math.ceil(cz + ri); z++) {
          const d2 = (x - cx) ** 2 + (y - cy) ** 2 + (z - cz) ** 2;
          if (d2 <= r2) {
            setVoxel(x, y, z, block);
          }
        }
      }
    }
  }

  function drawEllipsoid(cx, cy, cz, rx, ry, rz, block) {
    const minX = Math.floor(cx - rx), maxX = Math.ceil(cx + rx);
    const minY = Math.floor(cy - ry), maxY = Math.ceil(cy + ry);
    const minZ = Math.floor(cz - rz), maxZ = Math.ceil(cz + rz);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const norm = ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 + ((z - cz) / rz) ** 2;
          if (norm <= 1.0) {
            setVoxel(x, y, z, block);
          }
        }
      }
    }
  }

  function drawCapsule(p0, p1, r0, r1, block) {
    const dx = p1[0] - p0[0];
    const dy = p1[1] - p0[1];
    const dz = p1[2] - p0[2];
    const dist = Math.hypot(dx, dy, dz);
    const steps = Math.max(1, Math.ceil(dist * 3.0));
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const cx = p0[0] + dx * t;
      const cy = p0[1] + dy * t;
      const cz = p0[2] + dz * t;
      const r = r0 + (r1 - r0) * t;
      drawSphere(cx, cy, cz, r, block);
    }
  }

  const cx = 11.5;
  const cz = 11.5;

  // --- 1. PEDESTAL & ARCANE DAIS (Y: 0 to 5) ---
  const pedestalColumns = [];

  for (let y = 0; y <= 5; y++) {
    const tierRadius = 9.2 - y * 0.65;
    const maxManhattan = 13.0 - y * 0.8;

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = Math.abs(x - cx);
        const dz = Math.abs(z - cz);
        const dist2 = dx * dx + dz * dz;

        if (dist2 <= tierRadius * tierRadius && (dx + dz) <= maxManhattan) {
          if (y === 0) {
            pedestalColumns.push([x, z]);
          }

          let block = stonePrimary;

          // Pedestal ornamentation
          if (y === 0) {
            block = plinthBlock;
          } else if (y === 1) {
            if (dist2 > (tierRadius - 1.2) ** 2) {
              block = goldBlock;
            } else {
              block = stonePrimary;
            }
          } else if (y === 2) {
            if (Math.abs(Math.sqrt(dist2) - 6.0) < 0.8) {
              block = seaLantern;
            } else if (dx <= 0.6 || dz <= 0.6) {
              block = goldBlock;
            } else {
              block = stoneAccent;
            }
          } else if (y === 3) {
            if (dist2 > (tierRadius - 1.0) ** 2) {
              block = chiseledQuartz;
            } else {
              block = stonePrimary;
            }
          } else if (y === 4) {
            if ((dx <= 0.6 && dz <= 4.5) || (dz <= 0.6 && dx <= 4.5)) {
              block = goldBlock;
            } else if (Math.abs(Math.sqrt(dist2) - 3.8) < 0.6) {
              block = amethyst;
            } else {
              block = stonePrimary;
            }
          } else if (y === 5) {
            // Arcane star center
            if (dist2 <= 1.8 * 1.8) {
              block = seaLantern;
            } else if (dist2 <= 3.2 * 3.2 && (dx <= 0.6 || dz <= 0.6 || Math.abs(dx - dz) <= 0.6)) {
              block = goldBlock;
            } else {
              block = stonePrimary;
            }
          }

          setVoxel(x, y, z, block);
        }
      }
    }
  }

  // Four corner guardian pylons on the plinth
  const pylonCorners = [
    [5.0, 5.0],
    [18.0, 5.0],
    [5.0, 18.0],
    [18.0, 18.0],
  ];

  pylonCorners.forEach(([px, pz]) => {
    drawCapsule([px, 1, pz], [px, 5, pz], 1.2, 1.0, stoneAccent);
    setVoxel(px, 6, pz, chiseledQuartz);
    setVoxel(px, 7, pz, seaLantern);
    setVoxel(px, 8, pz, goldBlock);
  });

  // --- 2. HIND LEGS & ANCHORING TAIL (Y: 5 to 15) ---
  // Left Hind Leg
  drawCapsule([8.5, 5, 14.5], [8.5, 6, 14.5], 1.3, 1.2, goldBlock); // Hoof
  drawCapsule([8.5, 6, 14.5], [8.5, 10, 16.5], 1.2, 1.1, stoneAccent); // Hock
  drawCapsule([8.5, 10, 16.5], [9.5, 14.5, 13.5], 1.3, 1.8, stonePrimary); // Thigh

  // Right Hind Leg
  drawCapsule([14.5, 5, 14.5], [14.5, 6, 14.5], 1.3, 1.2, goldBlock); // Hoof
  drawCapsule([14.5, 6, 14.5], [14.5, 10, 16.5], 1.2, 1.1, stoneAccent); // Hock
  drawCapsule([14.5, 10, 16.5], [13.5, 14.5, 13.5], 1.3, 1.8, stonePrimary); // Thigh

  // Celestial Tail (Solid structural third pillar connected to pedestal)
  drawCapsule([cx, 14.5, 15.5], [cx, 12.0, 18.2], 1.5, 1.6, stonePrimary);
  drawCapsule([cx, 12.0, 18.2], [cx, 8.5, 19.5], 1.6, 1.7, amethyst);
  drawCapsule([cx, 8.5, 19.5], [cx, 5.0, 18.0], 1.7, 1.9, stonePrimary);
  drawCapsule([cx, 5.0, 18.0], [cx, 5.0, 15.5], 1.8, 2.0, goldBlock); // Welded to dais

  // Tail luminous ribbon inlays
  drawCapsule([cx, 13.0, 18.5], [cx, 7.5, 19.6], 0.7, 0.7, seaLantern);

  // --- 3. REARING TORSO & CHEST (Y: 13 to 23) ---
  // Pelvis / Rump
  drawEllipsoid(cx, 14.5, 13.8, 2.5, 2.2, 2.4, stonePrimary);

  // Mid-Barrel rising forward
  drawCapsule([cx, 14.5, 13.5], [cx, 18.5, 11.2], 2.4, 2.6, stonePrimary);

  // Broad Celestial Chest
  drawCapsule([cx, 18.5, 11.2], [cx, 22.5, 9.0], 2.6, 2.8, stonePrimary);
  drawEllipsoid(cx, 22.5, 9.0, 2.9, 2.6, 2.5, stonePrimary);

  // Golden pectoral emblem on chest
  drawSphere(cx, 22.0, 7.2, 1.1, goldBlock);
  drawSphere(cx, 22.0, 6.8, 0.6, seaLantern);

  // --- 4. FORELEGS (Striking Northward into mid-air) ---
  // Left Foreleg
  drawCapsule([8.5, 22.0, 9.5], [7.5, 25.0, 7.5], 1.3, 1.1, stonePrimary); // Upper arm
  drawCapsule([7.5, 25.0, 7.5], [6.5, 27.5, 5.5], 1.1, 0.9, stoneAccent);  // Forearm
  drawCapsule([6.5, 27.5, 5.5], [6.0, 28.5, 4.2], 1.0, 1.1, goldBlock);    // Striking hoof

  // Right Foreleg (Raised high in triumph)
  drawCapsule([14.5, 22.0, 9.5], [15.5, 26.0, 8.0], 1.3, 1.1, stonePrimary); // Upper arm
  drawCapsule([15.5, 26.0, 8.0], [16.5, 29.5, 6.5], 1.1, 0.9, stoneAccent);  // Forearm
  drawCapsule([16.5, 29.5, 6.5], [17.0, 30.8, 5.2], 1.0, 1.1, goldBlock);    // Striking hoof

  // --- 5. NECK, HEAD & CELESTIAL MANE ---
  // Arched Neck
  drawCapsule([cx, 22.0, 8.5], [cx, 27.0, 7.0], 2.1, 1.7, stonePrimary);
  drawCapsule([cx, 27.0, 7.0], [cx, 30.5, 5.8], 1.7, 1.4, stonePrimary);

  // Flowing Mane (Golden & Amethyst Crest billowing backward)
  drawCapsule([cx, 23.0, 10.2], [cx, 27.5, 8.8], 1.0, 1.1, goldBlock);
  drawCapsule([cx, 27.5, 8.8], [cx, 31.5, 7.5], 1.1, 1.0, amethyst);
  drawCapsule([cx, 31.5, 7.5], [cx, 33.5, 6.8], 0.9, 0.7, goldBlock);

  // Head & Jaw
  drawEllipsoid(cx, 31.2, 5.0, 1.5, 1.4, 1.6, stonePrimary);
  // Muzzle tapering down towards North
  drawCapsule([cx, 31.0, 4.5], [cx, 29.8, 2.8], 1.2, 0.9, stonePrimary);
  // Nostrils & Muzzle Tip
  drawSphere(cx, 29.5, 2.2, 0.75, goldBlock);

  // Pricked Ears
  drawCapsule([10.0, 32.5, 5.8], [9.2, 34.5, 6.5], 0.6, 0.35, stonePrimary);
  drawCapsule([13.0, 32.5, 5.8], [13.8, 34.5, 6.5], 0.6, 0.35, stonePrimary);

  // Glowing Celestial Eyes
  setVoxel(9.8, 31.5, 4.2, seaLantern);
  setVoxel(13.2, 31.5, 4.2, seaLantern);

  // --- 6. THE GOLDEN ALICORN HORN ---
  // Spiraling magical horn aimed toward enemy waters
  drawCapsule([cx, 32.4, 3.8], [cx, 34.2, 2.5], 0.8, 0.65, goldBlock);
  drawCapsule([cx, 34.2, 2.5], [cx, 36.0, 1.4], 0.65, 0.5, seaLantern);
  drawCapsule([cx, 36.0, 1.4], [cx, 37.2, 0.6], 0.5, 0.3, goldBlock);

  // --- 7. CELESTIAL GUARDIAN WINGS ---
  // Left Wing Spar & Feathers
  drawCapsule([9.0, 22.5, 10.5], [6.0, 26.5, 12.5], 1.4, 1.2, stonePrimary);
  drawCapsule([6.0, 26.5, 12.5], [4.0, 30.5, 15.0], 1.2, 1.0, stonePrimary);
  drawCapsule([4.0, 30.5, 15.0], [3.0, 34.0, 17.5], 1.0, 0.7, goldBlock);

  // Left Wing Secondary Feathers & Webbing
  drawCapsule([7.5, 24.0, 11.5], [4.8, 27.5, 15.0], 1.1, 0.8, stonePrimary);
  drawCapsule([4.8, 27.5, 15.0], [3.5, 31.0, 18.2], 0.8, 0.6, amethyst);
  drawCapsule([6.5, 22.5, 12.0], [4.5, 25.0, 16.5], 0.9, 0.7, stonePrimary);
  drawCapsule([4.5, 25.0, 16.5], [3.8, 28.0, 19.0], 0.7, 0.5, goldBlock);

  // Left Wing Glowing Rune Inlays
  drawCapsule([5.2, 28.5, 13.8], [3.8, 32.0, 16.2], 0.6, 0.5, seaLantern);

  // Right Wing Spar & Feathers
  drawCapsule([14.0, 22.5, 10.5], [17.0, 26.5, 12.5], 1.4, 1.2, stonePrimary);
  drawCapsule([17.0, 26.5, 12.5], [19.0, 30.5, 15.0], 1.2, 1.0, stonePrimary);
  drawCapsule([19.0, 30.5, 15.0], [20.0, 34.0, 17.5], 1.0, 0.7, goldBlock);

  // Right Wing Secondary Feathers & Webbing
  drawCapsule([15.5, 24.0, 11.5], [18.2, 27.5, 15.0], 1.1, 0.8, stonePrimary);
  drawCapsule([18.2, 27.5, 15.0], [19.5, 31.0, 18.2], 0.8, 0.6, amethyst);
  drawCapsule([16.5, 22.5, 12.0], [18.5, 25.0, 16.5], 0.9, 0.7, stonePrimary);
  drawCapsule([18.5, 25.0, 16.5], [19.2, 28.0, 19.0], 0.7, 0.5, goldBlock);

  // Right Wing Glowing Rune Inlays
  drawCapsule([17.8, 28.5, 13.8], [19.2, 32.0, 16.2], 0.6, 0.5, seaLantern);

  // --- 8. GROUND CONFORMANCE & FOUNDATION EXTENSION (Rule 6) ---
  // Every column occupied by the base extends downward into uneven terrain/seabed
  for (const [px, pz] of pedestalColumns) {
    const gh = api.heightAt(px, pz);
    if (gh < 0) {
      // Falling ground / cliff / shore: fill down with revetment & plinth
      const floorH = Math.max(-12, gh);
      for (let y = -1; y >= floorH; y--) {
        const mat = (y === -1) ? plinthBlock : revetmentBlock;
        api.set(px, y, pz, mat);
      }
    } else if (gh > 0) {
      // Rising ground: ensure solid masonry contact
      for (let y = 0; y <= gh && y < 5; y++) {
        if (!voxels[getIdx(px, y, pz)]) {
          voxels[getIdx(px, y, pz)] = plinthBlock;
        }
      }
    }
  }

  // --- 9. EMIT VOXELS DETERMINISTICALLY ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = voxels[getIdx(x, y, z)];
        if (b) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "Unicorn Colossus",
    seatY: 0,
    anchors: {
      front: [12, 0, 0],
      dais: [12, 5, 12],
      lookout: [12, 31, 5],
      horn_tip: [12, 37, 1],
    },
  };
}

pirate_dreadnought_bastion.source:
export const envelope = [32, 24, 28];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  // --- Theme block extraction with robust fallbacks ---
  const woodPlanks = api.theme.wood.planks;
  const woodLog = api.theme.wood.log;
  const woodStripped = api.theme.wood.stripped || api.theme.wood.log;
  const woodStairs = api.theme.wood.stairs;
  const woodSlab = api.theme.wood.slab;
  const woodFence = api.theme.wood.fence;
  const woodTrapdoor = api.theme.wood.trapdoor;

  const stonePrimary = api.theme.stone.primary;
  const stoneAccent = api.theme.stone.accent || api.theme.stone.primary;
  const stoneStairs = api.theme.stone.stairs;
  const stoneSlab = api.theme.stone.slab;
  const stoneWall = api.theme.stone.wall;

  const groundPlinth = api.theme.ground.plinth || stonePrimary;
  const groundPavement = api.theme.ground.pavement || stoneAccent;
  const roofStairs = api.theme.roof.stairs || woodStairs;
  const roofSlab = api.theme.roof.slab || woodSlab;
  const roofSolid = api.theme.roof.solid || woodPlanks;

  // War / Pirate accent props
  const cannonBarrel = "minecraft:dispenser[facing=north]";
  const cannonBody = "minecraft:polished_blackstone";
  const ironBlock = "minecraft:iron_block";
  const chain = "minecraft:chain";
  const lantern = "minecraft:lantern";
  const lanternHanging = "minecraft:lantern[hanging=true]";
  const campfire = "minecraft:campfire[lit=true]";
  const cauldron = "minecraft:cauldron";
  const blackWool = "minecraft:black_wool";
  const whiteWool = "minecraft:white_wool";
  const ironBars = "minecraft:iron_bars";
  const skull = "minecraft:wither_skeleton_skull";

  function stair(base, facing, half = "bottom") {
    const clean = base.split("[")[0];
    return `${clean}[facing=${facing},half=${half}]`;
  }

  function slab(base, type = "bottom") {
    const clean = base.split("[")[0];
    return `${clean}[type=${type}]`;
  }

  function trapdoor(base, facing = "north", half = "bottom", open = false) {
    const clean = base.split("[")[0];
    return `${clean}[facing=${facing},half=${half},open=${open}]`;
  }

  function logBlock(base, axis = "y") {
    const clean = base.split("[")[0];
    return `${clean}[axis=${axis}]`;
  }

  // --- Footprint definitions ---
  // Seat plane is at y = 4 (allowing downhill terrain skirt down to y=0)
  const SEAT_Y = 4;

  function isBastionBase(x, z) {
    // 4 Corner bastion towers (radius ~ 3.6)
    const dNW = Math.hypot(x - 7, z - 7);
    const dNE = Math.hypot(x - 24, z - 7);
    const dSW = Math.hypot(x - 7, z - 21);
    const dSE = Math.hypot(x - 24, z - 21);
    if (dNW <= 3.6 || dNE <= 3.6 || dSW <= 3.6 || dSE <= 3.6) return true;

    // Forward battery rampart (Z=2 to 7)
    if (z >= 2 && z <= 7) {
      const taper = 7 - z;
      if (x >= 7 + Math.floor(taper * 0.4) && x <= 24 - Math.floor(taper * 0.4)) {
        return true;
      }
    }

    // Main dreadnought keep hull (Z=7 to 23, X=5 to 26)
    if (z >= 7 && z <= 23 && x >= 5 && x <= 26) {
      return true;
    }

    // Rear stern gate (Z=23 to 26, X=8 to 23)
    if (z >= 23 && z <= 26) {
      const taper = z - 23;
      if (x >= 8 + Math.floor(taper * 0.6) && x <= 23 - Math.floor(taper * 0.6)) {
        return true;
      }
    }

    return false;
  }

  function isBastionWall(x, z) {
    if (!isBastionBase(x, z)) return false;
    const neighbors = [
      [x + 1, z],
      [x - 1, z],
      [x, z + 1],
      [x, z - 1],
    ];
    return neighbors.some(([nx, nz]) => !isBastionBase(nx, nz));
  }

  // --- 1. Foundation Skirts & Seat Plane ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isBastionBase(x, z)) {
        const h = Math.round(api.heightAt(x, z));
        const groundY = Math.max(0, Math.min(H - 1, SEAT_Y + h));
        const minY = Math.min(groundY, SEAT_Y);
        const maxY = Math.max(groundY, SEAT_Y);

        for (let y = minY; y <= maxY; y++) {
          const block = isBastionWall(x, z)
            ? (y < SEAT_Y ? groundPlinth : stonePrimary)
            : groundPavement;
          set(x, y, z, block);
        }
      }
    }
  }

  // --- 2. Lower Gun Deck & Stone Bastion (y = 4 to y = 8) ---
  for (let y = SEAT_Y; y <= 8; y++) {
    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        if (!isBastionBase(x, z)) continue;

        if (y === SEAT_Y) {
          set(x, y, z, isBastionWall(x, z) ? groundPlinth : woodPlanks);
        } else if (isBastionWall(x, z)) {
          // Masonry walls with occasional stone accents
          const isAccent = (x * 7 + y * 13 + z * 3) % 5 === 0;
          set(x, y, z, isAccent ? stoneAccent : stonePrimary);
        }
      }
    }
  }

  // Massive timber framing pilasters at keep corners
  const frameCorners = [
    [5, 8], [26, 8], [5, 20], [26, 20],
    [8, 24], [23, 24], [11, 4], [20, 4]
  ];
  for (const [cx, cz] of frameCorners) {
    for (let y = SEAT_Y + 1; y <= 8; y++) {
      set(cx, y, cz, logBlock(woodLog, "y"));
    }
  }

  // Lower Gun Deck Sea Battery: 4 Heavy Iron Cannon Ports at North Face (Z=2)
  const lowerGunX = [10, 13, 18, 21];
  for (const gx of lowerGunX) {
    // Punch gun embrasure
    set(gx, 5, 2, cannonBarrel);
    set(gx, 5, 3, cannonBody);
    set(gx, 5, 4, logBlock(woodLog, "z")); // Gun carriage
    set(gx, 6, 2, stair(stoneStairs, "south", "top")); // Arch lintel
    set(gx, 6, 3, ironBars);

    // Flanking iron reinforcements
    set(gx - 1, 5, 2, stoneAccent);
    set(gx + 1, 5, 2, stoneAccent);
  }

  // Rear Fortress Entrance Gate (Z=25..26, X=15..16, y=5..7)
  for (let gx = 15; gx <= 16; gx++) {
    for (let gy = 5; gy <= 7; gy++) {
      set(gx, gy, 25, null);
      set(gx, gy, 26, null);
    }
  }
  set(14, 5, 25, logBlock(woodLog, "y"));
  set(17, 5, 25, logBlock(woodLog, "y"));
  set(14, 6, 25, logBlock(woodLog, "y"));
  set(17, 6, 25, logBlock(woodLog, "y"));
  set(15, 7, 25, stair(stoneStairs, "east", "top"));
  set(16, 7, 25, stair(stoneStairs, "west", "top"));
  set(15, 7, 26, ironBars);
  set(16, 7, 26, ironBars);

  // Lower interior structural pillars
  const pillars = [[11, 11], [20, 11], [11, 17], [20, 17]];
  for (const [px, pz] of pillars) {
    for (let y = 5; y <= 8; y++) {
      set(px, y, pz, logBlock(woodLog, "y"));
    }
    set(px, 8, pz - 1, stair(woodStairs, "south", "top"));
    set(px, 8, pz + 1, stair(woodStairs, "north", "top"));
  }

  // Powder magazine crates & barrels in corners
  set(8, 5, 8, logBlock(woodLog, "y"));
  set(8, 5, 9, woodPlanks);
  set(9, 5, 8, ironBlock);
  set(23, 5, 8, logBlock(woodLog, "y"));
  set(23, 5, 9, woodPlanks);
  set(22, 5, 8, ironBlock);

  // --- 3. Mid Deck & Corbel Overhang (y = 8 to y = 9) ---
  // Machicolation corbels jutting out around outer perimeter
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isBastionWall(x, z)) {
        if (!isBastionBase(x, z - 1)) set(x, 8, z - 1, stair(stoneStairs, "north", "top"));
        if (!isBastionBase(x, z + 1)) set(x, 8, z + 1, stair(stoneStairs, "south", "top"));
        if (!isBastionBase(x - 1, z)) set(x - 1, 8, z, stair(stoneStairs, "west", "top"));
        if (!isBastionBase(x + 1, z)) set(x + 1, 8, z, stair(stoneStairs, "east", "top"));
      }
    }
  }

  // Mid Deck Flooring at y = 9
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isBastionBase(x, z)) {
        set(x, 9, z, woodPlanks);
      }
    }
  }

  // --- 4. Forward Upper Gun Deck & Carronades (Z=2 to 9, y=9 to 13) ---
  // Forward stone parapets & merlons
  for (let x = 6; x <= 25; x++) {
    for (let z = 2; z <= 9; z++) {
      if (isBastionBase(x, z)) {
        const isForwardWall =
          !isBastionBase(x, z - 1) ||
          !isBastionBase(x - 1, z) ||
          !isBastionBase(x + 1, z);
        if (isForwardWall) {
          set(x, 10, z, stonePrimary);
          // Crenellations
          if ((x + z) % 2 === 0) {
            set(x, 11, z, stoneWall);
          } else {
            set(x, 11, z, slab(stoneSlab, "bottom"));
          }
        }
      }
    }
  }

  // 3 Upper Deck Heavy Carronades facing North (-Z)
  const upperGuns = [9, 15, 22];
  for (const gx of upperGuns) {
    // Clear parapet port
    set(gx, 10, 3, cannonBarrel);
    set(gx, 10, 4, cannonBody);
    set(gx, 10, 5, logBlock(woodLog, "x"));
    set(gx, 11, 3, null); // Open sightline

    // Carriage wheel details
    set(gx - 1, 10, 5, trapdoor(woodTrapdoor, "east", "bottom", false));
    set(gx + 1, 10, 5, trapdoor(woodTrapdoor, "west", "bottom", false));

    // Cannonball piles
    set(gx - 1, 10, 6, skull);
    set(gx - 1, 10, 7, skull);
  }

  // Four Corner Bastion Turrets (NW, NE, SW, SE) at y=9..12
  const turretCenters = [
    [7, 7], [24, 7], [7, 21], [24, 21]
  ];
  for (const [tx, tz] of turretCenters) {
    for (let dx = -3; dx <= 3; dx++) {
      for (let dz = -3; dz <= 3; dz++) {
        const dist = Math.hypot(dx, dz);
        const x = tx + dx;
        const z = tz + dz;
        if (dist > 2.2 && dist <= 3.6) {
          set(x, 10, z, stonePrimary);
          set(x, 11, z, stoneWall);
          if ((dx + dz) % 2 === 0) {
            set(x, 12, z, slab(stoneSlab, "bottom"));
          }
        }
      }
    }
  }

  // Flaming battle braziers on forward turrets
  set(7, 10, 7, cauldron);
  set(7, 11, 7, campfire);
  set(24, 10, 7, cauldron);
  set(24, 11, 7, campfire);

  // --- 5. Dreadnought Sterncastle Citadel (Z=10 to 23, X=8 to 23, y=9 to 14) ---
  for (let y = 10; y <= 14; y++) {
    for (let x = 8; x <= 23; x++) {
      for (let z = 10; z <= 23; z++) {
        const isCitadelWall =
          x === 8 || x === 23 || z === 10 || z === 23;

        if (isCitadelWall) {
          // Vertical corner logs & stripped timber hull walls
          const isCorner =
            (x === 8 && (z === 10 || z === 16 || z === 23)) ||
            (x === 23 && (z === 10 || z === 16 || z === 23));

          if (isCorner) {
            set(x, y, z, logBlock(woodLog, "y"));
          } else if (y === 12) {
            // Horizontal timber belt band
            set(x, y, z, logBlock(woodStripped, x === 8 || x === 23 ? "z" : "x"));
          } else {
            set(x, y, z, woodPlanks);
          }
        }
      }
    }
  }

  // Broadside casemate sea-windows with iron bars on East & West sides
  for (let z = 13; z <= 20; z += 3) {
    set(8, 11, z, ironBars);
    set(8, 12, z, stair(woodStairs, "west", "top"));
    set(23, 11, z, ironBars);
    set(23, 12, z, stair(woodStairs, "east", "top"));
  }

  // Forward Commander Bridge viewports looking North over the strait (Z=10, X=13..18)
  for (let x = 13; x <= 18; x++) {
    if (x === 14 || x === 17) {
      set(x, 11, 10, logBlock(woodLog, "y"));
    } else {
      set(x, 11, 10, ironBars);
      set(x, 12, 10, stair(woodStairs, "south", "top"));
    }
  }

  // Rear Sternwalk / Captain's Balcony (Z=24, X=11 to 20, y=9..11)
  for (let x = 11; x <= 20; x++) {
    set(x, 9, 24, woodPlanks);
    set(x, 8, 24, stair(woodStairs, "north", "top")); // Cantilever corbels
    set(x, 10, 24, woodFence); // Balcony railing
  }
  set(11, 10, 24, logBlock(woodLog, "y"));
  set(20, 10, 24, logBlock(woodLog, "y"));
  set(11, 11, 24, lanternHanging);
  set(20, 11, 24, lanternHanging);

  // Doorways into citadel from front deck & rear balcony
  set(15, 10, 10, null);
  set(16, 10, 10, null);
  set(15, 11, 10, null);
  set(16, 11, 10, null);
  set(15, 10, 23, null);
  set(16, 10, 23, null);
  set(15, 11, 23, null);
  set(16, 11, 23, null);

  // --- 6. Citadel Fighting Roof & Pilot House (y=14 to 17) ---
  // Roof floor at y=14
  for (let x = 8; x <= 23; x++) {
    for (let z = 10; z <= 23; z++) {
      set(x, 14, z, woodPlanks);
    }
  }

  // Timber roof parapet & shields at y=15
  for (let x = 8; x <= 23; x++) {
    for (let z = 10; z <= 23; z++) {
      const isPerimeter = x === 8 || x === 23 || z === 10 || z === 23;
      if (isPerimeter) {
        set(x, 15, z, woodFence);
        if ((x + z) % 3 === 0) {
          set(x, 15, z, logBlock(woodLog, "y"));
          set(x, 16, z, slab(woodSlab, "bottom"));
        }
      }
    }
  }

  // Fortified Chart Cabin / Pilot House (Z=18 to 22, X=12 to 19, y=14 to 17)
  for (let y = 14; y <= 16; y++) {
    for (let x = 12; x <= 19; x++) {
      for (let z = 18; z <= 22; z++) {
        const isCabinWall = x === 12 || x === 19 || z === 18 || z === 22;
        if (isCabinWall) {
          set(x, y, z, woodPlanks);
        }
      }
    }
  }
  // Cabin arched roof at y=17
  for (let z = 18; z <= 22; z++) {
    set(11, 16, z, stair(roofStairs, "east"));
    set(12, 17, z, stair(roofStairs, "east"));
    for (let x = 13; x <= 18; x++) {
      set(x, 17, z, roofSolid);
    }
    set(19, 17, z, stair(roofStairs, "west"));
    set(20, 16, z, stair(roofStairs, "west"));
  }
  // Cabin doorway at north face (Z=18, X=15..16)
  set(15, 15, 18, null);
  set(16, 15, 18, null);

  // Smuggler's Heavy Cargo Crane on Port Side (X=7..8, Z=14, y=14..18)
  set(8, 15, 14, logBlock(woodLog, "y"));
  set(8, 16, 14, logBlock(woodLog, "y"));
  set(8, 17, 14, logBlock(woodLog, "y"));
  set(7, 17, 14, logBlock(woodLog, "x"));
  set(6, 17, 14, logBlock(woodLog, "x"));
  set(5, 17, 14, woodFence);
  set(5, 16, 14, chain);
  set(5, 15, 14, chain);
  set(5, 14, 14, woodPlanks); // Suspended cargo crate

  // --- 7. Dreadnought Grand Mast & Rigging (y=14 to 23) ---
  // Mast trunk from roof to sky (X=15..16, Z=15..16)
  for (let y = 14; y <= 22; y++) {
    set(15, y, 15, logBlock(woodLog, "y"));
    set(16, y, 15, logBlock(woodLog, "y"));
    set(15, y, 16, logBlock(woodLog, "y"));
    set(16, y, 16, logBlock(woodLog, "y"));
  }

  // Crow's Nest Lookout Platform at y=18..19
  for (let x = 14; x <= 17; x++) {
    for (let z = 14; z <= 17; z++) {
      const isRim = x === 14 || x === 17 || z === 14 || z === 17;
      set(x, 18, z, slab(woodSlab, "bottom"));
      if (isRim) {
        set(x, 19, z, woodFence);
      }
    }
  }
  set(14, 17, 15, lanternHanging);
  set(17, 17, 16, lanternHanging);

  // Yardarm Spar at y=21 (horizontal spar X=11 to 20, Z=15)
  for (let x = 11; x <= 20; x++) {
    set(x, 21, 15, logBlock(woodLog, "x"));
  }
  set(10, 21, 15, woodFence);
  set(21, 21, 15, woodFence);

  // Rigging shrouds angled down to citadel roof deck
  set(11, 20, 15, chain);
  set(10, 19, 15, chain);
  set(9, 18, 15, chain);
  set(9, 17, 15, chain);
  set(9, 16, 15, chain);

  set(20, 20, 15, chain);
  set(21, 19, 15, chain);
  set(22, 18, 15, chain);
  set(22, 17, 15, chain);
  set(22, 16, 15, chain);

  // Mast peak top at y=23
  set(15, 23, 15, woodFence);
  set(16, 23, 15, woodFence);

  // --- 8. The Tattered Skull & Crossbones Pirate Banner (Jolly Roger) ---
  // Suspended from yardarm at Z=14, facing directly NORTH (-Z) toward the strait!
  // Size: Width 7 (X=13..19), Height 5 (Y=15..19)
  const bannerPixels = [
    // Y = 19: Top crossbone tips & skull top
    [blackWool, whiteWool, blackWool, blackWool, blackWool, whiteWool, blackWool],
    // Y = 18: Full skull cranium
    [blackWool, blackWool, whiteWool, whiteWool, whiteWool, blackWool, blackWool],
    // Y = 17: Eye sockets & side crossbone ends
    [whiteWool, blackWool, blackWool, whiteWool, blackWool, blackWool, whiteWool],
    // Y = 16: Teeth / jaw & bottom crossbone crossings
    [blackWool, whiteWool, whiteWool, blackWool, whiteWool, whiteWool, blackWool],
    // Y = 15: Tattered bottom fringes with cutouts
    [null, blackWool, null, blackWool, null, blackWool, null],
  ];

  for (let r = 0; r < bannerPixels.length; r++) {
    const y = 19 - r;
    const row = bannerPixels[r];
    for (let c = 0; c < row.length; c++) {
      const x = 13 + c;
      const blk = row[c];
      if (blk) {
        set(x, y, 14, blk);
      }
    }
  }

  // --- 9. Write Voxel Buffer to API ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const blk = grid[x][y][z];
        if (blk !== null) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  // --- 10. Return Contract Result ---
  return {
    name: "pirate_dreadnought_bastion",
    seatY: SEAT_Y,
    anchors: {
      front: [16, 9, 0],   // Forward battery aiming North across the strait
      door: [16, 4, 26],   // Rear fortress gate approach
    },
    interiors: [
      {
        min: [8, 5, 8],
        max: [23, 7, 20],
        kind: "hall",      // Lower gun deck & munitions arsenal
      },
      {
        min: [10, 10, 12],
        max: [21, 13, 21],
        kind: "quarters",  // Captain's war room & redoubt
      },
    ],
  };
}

shore_cannon_battery.source:
export const envelope = [13, 13, 11];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;
  const deckY = 4;
  const variant = api.instance.index % 6;

  // Resolve palette roles from the settlement theme with safe fallbacks
  const woodPlanks = api.theme.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood?.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood?.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood?.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone?.accent || "minecraft:cobblestone";
  const stoneStairs = api.theme.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone?.wall || "minecraft:stone_brick_wall";

  const groundPavement = api.theme.ground?.pavement || "minecraft:cobblestone";
  const groundRevetment = api.theme.ground?.revetment || "minecraft:stone_bricks";
  const groundPlinth = api.theme.ground?.plinth || "minecraft:smooth_stone";
  const groundScree = api.theme.ground?.scree || "minecraft:gravel";
  const groundSlab = api.theme.ground?.slab || "minecraft:cobblestone_slab";

  const roofSolid = api.theme.roof?.solid || "minecraft:dark_oak_planks";
  const roofStairs = api.theme.roof?.stairs || "minecraft:dark_oak_stairs";
  const roofSlab = api.theme.roof?.slab || "minecraft:dark_oak_slab";

  function withState(blockStr, stateStr) {
    if (!blockStr) return stateStr;
    const base = blockStr.split("[")[0];
    return `${base}[${stateStr}]`;
  }

  function setBlock(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    api.set(x, y, z, block);
  }

  // 1. Foundation & Substructure conforming to real ground at every column
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const inPlatform = x >= 1 && x <= 11 && z >= 1 && z <= 8;
      const inRamp = x >= 3 && x <= 9 && z >= 9 && z <= 10;
      const inFlank = (x === 0 || x === 12) && z >= 1 && z <= 8;

      if (!inPlatform && !inRamp && !inFlank) continue;

      const gh = Math.round(api.heightAt(x, z));
      const groundLocalY = Math.max(0, Math.min(H - 1, seatY + gh));
      const targetTopY = inRamp ? (z === 9 ? deckY - 1 : deckY - 2) : deckY - 1;

      // Fill from local ground up to target sub-floor level
      const startY = Math.min(groundLocalY, targetTopY);
      for (let y = Math.max(0, Math.min(startY, groundLocalY)); y <= targetTopY; y++) {
        const isPerimeter = x === 0 || x === W - 1 || z === 0 || z === 1 || z === 8;
        if (isPerimeter && (z <= 2 || x === 0 || x === W - 1)) {
          // Timber sea pilings and stone revetments on the seaward and flank edges
          if (y % 2 === 0) {
            setBlock(x, y, z, withState(woodLog, "axis=y"));
          } else {
            setBlock(x, y, z, groundRevetment);
          }
        } else {
          setBlock(x, y, z, (x + z + y) % 3 === 0 ? stoneAccent : stonePrimary);
        }
      }

      // If ground rises above seat plane, integrate retaining structure
      if (groundLocalY >= deckY) {
        setBlock(x, deckY, z, groundPavement);
      }
    }
  }

  // 2. Main Battery Gun Deck (y = deckY = 4)
  for (let x = 1; x <= 11; x++) {
    for (let z = 2; z <= 8; z++) {
      if (z === 2 || z === 8 || x === 1 || x === 11) {
        // Heavy log stringer rim
        const axis = (z === 2 || z === 8) ? "axis=x" : "axis=z";
        setBlock(x, deckY, z, withState(woodLog, axis));
      } else {
        // Planks flooring with timber wear patterns
        const deckMaterial = ((x * 3 + z * 5) % 4 === 0) ? woodStripped : woodPlanks;
        setBlock(x, deckY, z, deckMaterial);
      }
    }
  }

  // Outer timber curb & flank posts
  for (let z = 1; z <= 8; z++) {
    setBlock(0, deckY, z, withState(woodLog, "axis=z"));
    setBlock(12, deckY, z, withState(woodLog, "axis=z"));
  }

  // 3. Rear Entry Stairway (z = 8..10)
  for (let x = 4; x <= 8; x++) {
    setBlock(x, deckY, 8, withState(woodStairs, "facing=south,half=bottom"));
    setBlock(x, deckY - 1, 9, withState(woodStairs, "facing=south,half=bottom"));
    setBlock(x, deckY - 2, 10, withState(groundSlab, "type=bottom"));
  }
  // Stair handrails
  setBlock(3, deckY + 1, 8, woodFence);
  setBlock(3, deckY, 9, woodFence);
  setBlock(9, deckY + 1, 8, woodFence);
  setBlock(9, deckY, 9, woodFence);

  // 4. Parapet & Breastwork along North Seaward Wall (z = 1..2)
  for (let x = 1; x <= 11; x++) {
    setBlock(x, deckY, 1, withState(woodLog, "axis=x"));
    // Breastwork base (y = deckY + 1 = 5)
    setBlock(x, deckY + 1, 1, groundRevetment);
    // Sandbag / log coping (y = deckY + 2 = 6)
    setBlock(x, deckY + 2, 1, withState(woodSlab, "type=bottom"));
  }
  // Flank protective walls
  for (let z = 2; z <= 7; z++) {
    setBlock(1, deckY + 1, z, stoneWall);
    setBlock(11, deckY + 1, z, stoneWall);
  }

  // Helper: Open gun port embrasure in the parapet
  function makeEmbrasure(gunX) {
    setBlock(gunX, deckY, 1, withState(woodPlanks, ""));
    setBlock(gunX, deckY + 1, 1, withState(woodSlab, "type=bottom"));
    setBlock(gunX, deckY + 2, 1, "minecraft:air");
    // Mantlet cheeks
    setBlock(gunX - 1, deckY + 1, 1, withState(woodLog, "axis=y"));
    setBlock(gunX + 1, deckY + 1, 1, withState(woodLog, "axis=y"));
    setBlock(gunX - 1, deckY + 2, 1, withState(woodTrapdoor, "facing=south,half=bottom,open=false"));
    setBlock(gunX + 1, deckY + 2, 1, withState(woodTrapdoor, "facing=south,half=bottom,open=false"));
  }

  // Helper: Standard Naval Cannon
  function buildNavalCannon(cx, cz, cy) {
    makeEmbrasure(cx);
    // Carriage bed & wheels
    setBlock(cx, cy, cz, woodPlanks);
    setBlock(cx - 1, cy, cz, withState(woodTrapdoor, "facing=east,half=bottom,open=false"));
    setBlock(cx + 1, cy, cz, withState(woodTrapdoor, "facing=west,half=bottom,open=false"));
    // Barrel
    setBlock(cx, cy + 1, cz + 1, withState(woodStairs, "facing=south,half=top"));
    setBlock(cx, cy + 1, cz, "minecraft:cauldron");
    setBlock(cx, cy + 1, cz - 1, "minecraft:dispenser[facing=north]");
    setBlock(cx, cy + 1, cz - 2, "minecraft:polished_blackstone_wall");
    // Recoil tackle
    setBlock(cx, cy, cz + 1, "minecraft:chain[axis=z]");
  }

  // Helper: Heavy Long-Range Siege Cannon
  function buildHeavySiegeCannon(cx, cz, cy) {
    makeEmbrasure(cx);
    // Reinforced carriage
    setBlock(cx, cy, cz, woodPlanks);
    setBlock(cx, cy, cz + 1, woodPlanks);
    setBlock(cx - 1, cy, cz, withState(woodStairs, "facing=north,half=bottom"));
    setBlock(cx + 1, cy, cz, withState(woodStairs, "facing=north,half=bottom"));
    // Long cast iron barrel
    setBlock(cx, cy + 1, cz + 1, "minecraft:polished_blackstone");
    setBlock(cx, cy + 1, cz, "minecraft:dispenser[facing=north]");
    setBlock(cx, cy + 1, cz - 1, "minecraft:polished_blackstone");
    setBlock(cx, cy + 1, cz - 2, "minecraft:polished_blackstone_wall");
    // Trunnions & elevation ironwork
    setBlock(cx, cy + 2, cz, "minecraft:iron_bars");
    setBlock(cx, cy, cz + 2, "minecraft:chain[axis=z]");
  }

  // Helper: Ammunition shot pile
  function buildShotRack(sx, sz, sy) {
    setBlock(sx, sy, sz, "minecraft:coal_block");
    setBlock(sx, sy + 1, sz, "minecraft:wither_skeleton_skull[rotation=0]");
    setBlock(sx + 1, sy, sz, "minecraft:coal_block");
  }

  // 5. Apply Variant Specific Emplacements & Shore Battery Themes
  if (variant === 0) {
    // VARIANT 0: Twin 32-Pounder Naval Redoubt with Hot-Shot Furnace & Signal Mast
    buildHeavySiegeCannon(3, 3, deckY);
    buildHeavySiegeCannon(9, 3, deckY);

    // Center Hot-Shot Furnace (heats iron cannonballs red-hot)
    setBlock(6, deckY, 4, stonePrimary);
    setBlock(6, deckY + 1, 4, "minecraft:blast_furnace[facing=north,lit=true]");
    setBlock(6, deckY + 2, 4, stoneWall);
    setBlock(6, deckY + 3, 4, stoneWall);
    setBlock(5, deckY + 1, 4, "minecraft:iron_bars");
    setBlock(7, deckY + 1, 4, "minecraft:iron_bars");
    buildShotRack(5, 5, deckY);

    // Powder barrels on West flank
    setBlock(2, deckY + 1, 5, "minecraft:barrel[facing=up]");
    setBlock(2, deckY + 1, 6, "minecraft:barrel[facing=up]");
    setBlock(2, deckY + 2, 5, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));

    // East Signal Mast with yardarm and pirate pennant
    for (let y = deckY + 1; y <= deckY + 7; y++) {
      setBlock(10, y, 5, withState(woodLog, "axis=y"));
    }
    // Cross yardarm
    setBlock(9, deckY + 6, 5, woodFence);
    setBlock(11, deckY + 6, 5, woodFence);
    setBlock(9, deckY + 5, 5, "minecraft:lantern[hanging=true]");
    // Black pirate flag
    setBlock(10, deckY + 7, 4, "minecraft:black_wool");
    setBlock(10, deckY + 6, 4, "minecraft:black_wool");
    setBlock(10, deckY + 7, 3, "minecraft:red_wool");

  } else if (variant === 1) {
    // VARIANT 1: Triple Casemate Battery with Splinter-Proof Log Canopy
    buildNavalCannon(2, 3, deckY);
    buildNavalCannon(6, 3, deckY);
    buildNavalCannon(10, 3, deckY);

    // Swab & water tubs between guns
    setBlock(4, deckY + 1, 4, "minecraft:cauldron");
    setBlock(8, deckY + 1, 4, "minecraft:cauldron");
    buildShotRack(4, 5, deckY);
    buildShotRack(8, 5, deckY);

    // Casemate timber columns
    const casemateCols = [[1, 3], [5, 3], [7, 3], [11, 3], [1, 7], [5, 7], [7, 7], [11, 7]];
    for (const [cx, cz] of casemateCols) {
      for (let y = deckY + 1; y <= deckY + 3; y++) {
        setBlock(cx, y, cz, withState(woodLog, "axis=y"));
      }
    }

    // Splinter-proof roof at y = deckY + 4
    for (let x = 1; x <= 11; x++) {
      for (let z = 3; z <= 7; z++) {
        setBlock(x, deckY + 4, z, roofSolid);
        // Sandbag reinforcement on top
        if ((x + z) % 2 === 0) {
          setBlock(x, deckY + 5, z, withState(woodSlab, "type=bottom"));
        } else {
          setBlock(x, deckY + 5, z, groundScree);
        }
      }
    }

    // Lookout ladder & signal lantern on roof
    setBlock(11, deckY + 1, 6, "minecraft:ladder[facing=north]");
    setBlock(11, deckY + 2, 6, "minecraft:ladder[facing=north]");
    setBlock(11, deckY + 3, 6, "minecraft:ladder[facing=north]");
    setBlock(6, deckY + 6, 5, woodFence);
    setBlock(6, deckY + 7, 5, "minecraft:lantern[hanging=false]");

  } else if (variant === 2) {
    // VARIANT 2: Grand Bombard Mortar, Auxiliary Naval Gun & Shell Crane
    buildNavalCannon(2, 3, deckY);

    // Central Bombard Mortar (angled upward siege mortar)
    setBlock(6, deckY, 4, "minecraft:polished_blackstone");
    setBlock(5, deckY + 1, 4, stoneWall);
    setBlock(7, deckY + 1, 4, stoneWall);
    setBlock(6, deckY + 1, 5, stoneWall);
    setBlock(6, deckY + 1, 3, "minecraft:polished_blackstone_stairs[facing=north,half=bottom]");
    // Mortar chamber & tube
    setBlock(6, deckY + 1, 4, "minecraft:cauldron");
    setBlock(6, deckY + 2, 4, "minecraft:hopper[facing=north]");
    setBlock(6, deckY + 3, 4, "minecraft:iron_bars");

    // Heavy mortar bomb stack
    setBlock(4, deckY + 1, 5, "minecraft:coal_block");
    setBlock(4, deckY + 2, 5, "minecraft:wither_skeleton_skull[rotation=0]");
    setBlock(4, deckY + 1, 6, "minecraft:barrel[facing=up]");

    // Shell Crane / Derrick on East Flank (x = 10, z = 4)
    for (let y = deckY + 1; y <= deckY + 5; y++) {
      setBlock(10, y, 4, withState(woodLog, "axis=y"));
    }
    // Crane boom reaching seaward
    setBlock(10, deckY + 5, 3, woodFence);
    setBlock(10, deckY + 5, 2, woodFence);
    setBlock(10, deckY + 4, 2, "minecraft:chain[axis=y]");
    setBlock(10, deckY + 3, 2, "minecraft:iron_bars");
    // Winch drum
    setBlock(10, deckY + 1, 5, "minecraft:barrel[facing=north]");
    setBlock(10, deckY + 2, 5, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));

  } else if (variant === 3) {
    // VARIANT 3: Battle Action Battery (Recoiled Gun & Repaired Breach)
    // West Gun has just fired and recoiled back!
    makeEmbrasure(3);
    setBlock(3, deckY, 5, woodPlanks);
    setBlock(3, deckY + 1, 5, "minecraft:cauldron");
    setBlock(3, deckY + 1, 4, "minecraft:dispenser[facing=north]");
    setBlock(3, deckY + 1, 3, "minecraft:polished_blackstone_wall");
    setBlock(3, deckY + 1, 6, "minecraft:blackstone"); // Gunpowder scorch
    setBlock(2, deckY + 1, 4, "minecraft:cauldron");   // Cooling water

    // East Gun is in battery, ready
    buildHeavySiegeCannon(9, 3, deckY);

    // Center parapet breach from incoming shell (repaired with sandbags/gabions)
    setBlock(6, deckY + 1, 1, groundScree);
    setBlock(6, deckY + 2, 1, withState(woodStairs, "facing=north,half=bottom"));
    setBlock(5, deckY + 1, 2, withState(woodPlanks, ""));
    setBlock(7, deckY + 1, 2, groundScree);

    // West Field Medical / Rations station
    setBlock(1, deckY + 1, 5, "minecraft:barrel[facing=up]");
    setBlock(1, deckY + 1, 6, withState(woodStairs, "facing=east,half=bottom"));

    // East Lookout Tower on 4 log legs
    for (let y = deckY + 1; y <= deckY + 5; y++) {
      setBlock(9, y, 6, withState(woodLog, "axis=y"));
      setBlock(11, y, 6, withState(woodLog, "axis=y"));
      setBlock(9, y, 7, withState(woodLog, "axis=y"));
      setBlock(11, y, 7, withState(woodLog, "axis=y"));
    }
    // Crow's nest platform & brazier
    for (let tx = 9; tx <= 11; tx++) {
      for (let tz = 6; tz <= 7; tz++) {
        setBlock(tx, deckY + 6, tz, woodPlanks);
      }
    }
    setBlock(10, deckY + 7, 6, "minecraft:lantern[hanging=false]");
    setBlock(10, deckY + 7, 7, withState(woodLog, "axis=y"));
    setBlock(10, deckY + 8, 7, "minecraft:black_wool");

  } else if (variant === 4) {
    // VARIANT 4: Heavy Stone Bastion with Turntable Mounts & Chart Casemate
    buildHeavySiegeCannon(3, 3, deckY);
    buildHeavySiegeCannon(9, 3, deckY);

    // Turntable circular rings under the guns
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        if (Math.abs(dx) + Math.abs(dz) === 1) {
          setBlock(3 + dx, deckY, 3 + dz, groundPlinth);
          setBlock(9 + dx, deckY, 3 + dz, groundPlinth);
        }
      }
    }

    // Officer's Command Casemate in center rear (x = 5..7, z = 5..7)
    for (let y = deckY + 1; y <= deckY + 3; y++) {
      setBlock(5, y, 7, withState(woodLog, "axis=y"));
      setBlock(7, y, 7, withState(woodLog, "axis=y"));
      setBlock(5, y, 5, withState(woodLog, "axis=y"));
      setBlock(7, y, 5, withState(woodLog, "axis=y"));
    }
    // Chart Casemate Roof
    for (let x = 5; x <= 7; x++) {
      for (let z = 5; z <= 7; z++) {
        setBlock(x, deckY + 4, z, roofSolid);
      }
    }
    // Interior: Map Table & Spyglass bench
    setBlock(6, deckY + 1, 6, "minecraft:cartography_table");
    setBlock(6, deckY + 2, 6, "minecraft:lantern[hanging=false]");
    buildShotRack(4, 4, deckY);
    buildShotRack(8, 4, deckY);

  } else {
    // VARIANT 5: Admiral's Stepped Redoubt with Raised Quarterdeck & Rigging
    buildHeavySiegeCannon(6, 3, deckY); // Heavy Center Gun
    buildNavalCannon(2, 3, deckY);        // Left Sponson Gun
    buildNavalCannon(10, 3, deckY);       // Right Sponson Gun

    // Raised Rear Quarterdeck at y = deckY + 2 (x = 3..9, z = 6..8)
    for (let x = 3; x <= 9; x++) {
      for (let z = 6; z <= 8; z++) {
        setBlock(x, deckY + 1, z, withState(woodLog, "axis=y"));
        setBlock(x, deckY + 2, z, woodPlanks);
      }
    }
    // Quarterdeck access steps
    setBlock(6, deckY + 1, 5, withState(woodStairs, "facing=south,half=bottom"));
    setBlock(6, deckY + 2, 5, withState(woodStairs, "facing=south,half=bottom"));

    // Dual Rigging Masts at x = 4, 8 on quarterdeck
    for (let y = deckY + 3; y <= deckY + 6; y++) {
      setBlock(4, y, 7, withState(woodLog, "axis=y"));
      setBlock(8, y, 7, withState(woodLog, "axis=y"));
    }
    // Stay line chain & warning bell between masts
    for (let x = 5; x <= 7; x++) {
      setBlock(x, deckY + 6, 7, "minecraft:chain[axis=x]");
    }
    setBlock(6, deckY + 5, 7, "minecraft:lantern[hanging=true]");
    setBlock(4, deckY + 7, 7, "minecraft:red_wool");
    setBlock(8, deckY + 7, 7, "minecraft:black_wool");
  }

  return {
    name: "Shore Cannon Battery",
    seatY,
    anchors: {
      front: [Math.floor(W / 2), deckY, 0],
      entry: [Math.floor(W / 2), seatY, D - 1]
    }
  };
}

arcane_ward_crystal.source:
export const envelope = [9, 16, 9];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;
  const cx = 4;
  const cz = 4;

  const instIndex = api.instance?.index ?? 0;
  const variant = instIndex % 6;

  // Resolve palette from theme with safe vanilla fallbacks
  const theme = api.theme ?? {};
  const stPrimary = theme.stone?.primary ?? "minecraft:smooth_quartz";
  const stAccent = theme.stone?.accent ?? "minecraft:chiseled_quartz_block";
  const stStairs = theme.stone?.stairs ?? "minecraft:quartz_stairs";
  const stSlab = theme.stone?.slab ?? "minecraft:quartz_slab";
  const stWall = theme.stone?.wall ?? "minecraft:diorite_wall";
  const grPlinth = theme.ground?.plinth ?? "minecraft:quartz_bricks";
  const grPavement = theme.ground?.pavement ?? "minecraft:smooth_quartz";

  // Grid for bounds & occupancy tracking
  const occupied = new Set();
  const coordKey = (x, y, z) => `${x},${y},${z}`;

  function setBlock(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    api.set(x, y, z, block);
    occupied.add(coordKey(x, y, z));
  }

  function getBlockName(blockString) {
    return blockString.split("[")[0];
  }

  function withState(blockString, state) {
    return `${getBlockName(blockString)}[${state}]`;
  }

  // 6-connected Manhattan line drawer for physical energy/chain tethers
  function connectLine6(x0, y0, z0, x1, y1, z1, blockFn) {
    let curX = Math.round(x0);
    let curY = Math.round(y0);
    let curZ = Math.round(z0);
    const targetX = Math.round(x1);
    const targetY = Math.round(y1);
    const targetZ = Math.round(z1);

    setBlock(curX, curY, curZ, blockFn(curX, curY, curZ, 0, 0, 0, true));

    while (curX !== targetX || curY !== targetY || curZ !== targetZ) {
      const dx = targetX - curX;
      const dy = targetY - curY;
      const dz = targetZ - curZ;

      const absDx = Math.abs(dx);
      const absDy = Math.abs(dy);
      const absDz = Math.abs(dz);

      let stepX = 0;
      let stepY = 0;
      let stepZ = 0;

      if (absDy >= absDx && absDy >= absDz && absDy > 0) {
        stepY = Math.sign(dy);
      } else if (absDx >= absDz && absDx > 0) {
        stepX = Math.sign(dx);
      } else if (absDz > 0) {
        stepZ = Math.sign(dz);
      } else if (absDy > 0) {
        stepY = Math.sign(dy);
      } else if (absDx > 0) {
        stepX = Math.sign(dx);
      }

      curX += stepX;
      curY += stepY;
      curZ += stepZ;

      const isEnd = curX === targetX && curY === targetY && curZ === targetZ;
      setBlock(curX, curY, curZ, blockFn(curX, curY, curZ, stepX, stepY, stepZ, isEnd));
    }
  }

  // --- 1. Ground Conformance & Plinth Dais ---
  const daisRadius = 3.9;

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dist = Math.hypot(x - cx, z - cz);
      if (dist <= daisRadius) {
        const groundH = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, Math.round(seatY + groundH)));

        const fillBottom = 0;
        const fillTop = Math.max(groundY, seatY);

        for (let y = fillBottom; y <= fillTop; y++) {
          let block = stPrimary;
          if (y < seatY) {
            block = ((x + y + z) % 3 === 0) ? grPavement : (y === 0 ? grPlinth : stPrimary);
          } else if (y === seatY) {
            // Floor pattern at seat level
            if (dist > 3.2) {
              const dx = x - cx;
              const dz = z - cz;
              if (Math.abs(dx) >= Math.abs(dz)) {
                block = dx > 0 ? withState(stStairs, "facing=west,half=bottom") : withState(stStairs, "facing=east,half=bottom");
              } else {
                block = dz > 0 ? withState(stStairs, "facing=north,half=bottom") : withState(stStairs, "facing=south,half=bottom");
              }
            } else if (dist > 2.0) {
              // Ritual rune ring
              if (variant === 0) {
                block = (x + z) % 2 === 0 ? "minecraft:amethyst_block" : stAccent;
              } else if (variant === 1) {
                block = (x * z) % 2 === 0 ? "minecraft:crying_obsidian" : "minecraft:gold_block";
              } else if (variant === 2) {
                block = (x + z) % 2 === 0 ? "minecraft:gold_block" : "minecraft:smooth_quartz";
              } else if (variant === 3) {
                block = (x + z) % 2 === 0 ? "minecraft:raw_gold_block" : "minecraft:quartz_bricks";
              } else if (variant === 4) {
                block = (x * z) % 2 === 0 ? "minecraft:amethyst_block" : "minecraft:sea_lantern";
              } else {
                block = (x + z) % 2 === 0 ? "minecraft:smooth_quartz" : "minecraft:amethyst_block";
              }
            } else {
              block = dist <= 0.8 ? "minecraft:sea_lantern" : stAccent;
            }
          } else {
            block = stPrimary;
          }
          setBlock(x, y, z, block);
        }
      }
    }
  }

  // North front approach entrance at seatY
  setBlock(cx, seatY, 0, withState(stStairs, "facing=north,half=bottom"));
  setBlock(cx - 1, seatY, 0, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx + 1, seatY, 0, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx - 1, seatY + 1, 0, "minecraft:gold_block");
  setBlock(cx + 1, seatY + 1, 0, "minecraft:gold_block");

  // --- 2. Raised Ritual Sub-Dais (y = 4) ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dist = Math.hypot(x - cx, z - cz);
      if (dist <= 2.5) {
        if (dist > 1.8) {
          const dx = x - cx;
          const dz = z - cz;
          if (Math.abs(dx) >= Math.abs(dz)) {
            setBlock(x, seatY + 1, z, dx > 0 ? withState(stStairs, "facing=west,half=bottom") : withState(stStairs, "facing=east,half=bottom"));
          } else {
            setBlock(x, seatY + 1, z, dz > 0 ? withState(stStairs, "facing=north,half=bottom") : withState(stStairs, "facing=south,half=bottom"));
          }
        } else {
          setBlock(x, seatY + 1, z, "minecraft:smooth_quartz");
        }
      }
    }
  }

  // --- 3. Anchor Pylons & Golden Runic Chains ---
  let pylonCoords = [];
  if (variant === 0 || variant === 2 || variant === 4) {
    pylonCoords = [[2, 2], [6, 2], [2, 6], [6, 6]];
  } else if (variant === 1 || variant === 3) {
    pylonCoords = [[4, 1], [1, 4], [7, 4], [4, 7]];
  } else {
    pylonCoords = [[2, 2], [6, 2], [2, 6], [6, 6], [4, 1], [1, 4], [7, 4], [4, 7]];
  }

  const pylonTops = [];
  for (let i = 0; i < pylonCoords.length; i++) {
    const [px, pz] = pylonCoords[i];
    const pHeight = 3 + (i % 2) + (variant % 2);
    const topY = seatY + 1 + pHeight;

    for (let y = seatY + 1; y <= topY; y++) {
      if (y === seatY + 1) {
        setBlock(px, y, pz, stAccent);
      } else if (y === topY - 1) {
        setBlock(px, y, pz, "minecraft:chiseled_quartz_block");
      } else if (y === topY) {
        setBlock(px, y, pz, (variant === 1 || variant === 3) ? "minecraft:gilded_blackstone" : "minecraft:gold_block");
      } else {
        setBlock(px, y, pz, "minecraft:quartz_pillar[axis=y]");
      }
    }

    if (topY + 1 < H) {
      if (variant === 0 || variant === 3) {
        setBlock(px, topY + 1, pz, "minecraft:lightning_rod[facing=up]");
      } else if (variant === 4) {
        setBlock(px, topY + 1, pz, "minecraft:end_rod[facing=up]");
      } else {
        setBlock(px, topY + 1, pz, stWall);
      }
    }
    pylonTops.push([px, topY, pz]);
  }

  // --- 4. Central Crystal Spire Variations ---

  function buildCoreBlock(x, y, z, block) {
    setBlock(x, y, z, block);
  }

  if (variant === 0) {
    // Grand Zenith Amethyst Ward
    for (let y = 5; y <= 14; y++) {
      if (y <= 6) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            buildCoreBlock(cx + dx, y, cz + dz, "minecraft:smooth_quartz");
          }
        }
      } else if (y <= 8) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            const isCenter = dx === 0 && dz === 0;
            const isCorner = Math.abs(dx) === 1 && Math.abs(dz) === 1;
            if (isCenter) {
              buildCoreBlock(cx, y, cz, "minecraft:sea_lantern");
            } else if (isCorner) {
              buildCoreBlock(cx + dx, y, cz + dz, "minecraft:raw_gold_block");
            } else {
              buildCoreBlock(cx + dx, y, cz + dz, "minecraft:amethyst_block");
            }
          }
        }
        buildCoreBlock(cx + 2, y, cz, "minecraft:amethyst_block");
        buildCoreBlock(cx - 2, y, cz, "minecraft:amethyst_block");
        buildCoreBlock(cx, y, cz + 2, "minecraft:amethyst_block");
        buildCoreBlock(cx, y, cz - 2, "minecraft:amethyst_block");
      } else if (y <= 10) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            if (Math.abs(dx) + Math.abs(dz) <= 1) {
              buildCoreBlock(cx + dx, y, cz + dz, "minecraft:amethyst_block");
            } else {
              buildCoreBlock(cx + dx, y, cz + dz, "minecraft:tinted_glass");
            }
          }
        }
      } else if (y <= 12) {
        buildCoreBlock(cx, y, cz, "minecraft:budding_amethyst");
        buildCoreBlock(cx + 1, y, cz, "minecraft:amethyst_block");
        buildCoreBlock(cx - 1, y, cz, "minecraft:amethyst_block");
        buildCoreBlock(cx, y, cz + 1, "minecraft:amethyst_block");
        buildCoreBlock(cx, y, cz - 1, "minecraft:amethyst_block");
      } else {
        buildCoreBlock(cx, y, cz, "minecraft:amethyst_block");
      }
    }
    setBlock(cx, 15, cz, "minecraft:amethyst_cluster[facing=up]");

  } else if (variant === 1) {
    // Twin Harmonic Spires
    for (let y = 5; y <= 7; y++) {
      for (let dx = -1; dx <= 1; dx++) {
        for (let dz = -1; dz <= 1; dz++) {
          buildCoreBlock(cx + dx, y, cz + dz, (dx === 0 && dz === 0) ? "minecraft:sea_lantern" : "minecraft:smooth_quartz");
        }
      }
    }
    // Bifurcate at y = 8 into West Amethyst & East Quartz
    for (let y = 8; y <= 14; y++) {
      // West Spire (cx - 1, cz)
      buildCoreBlock(cx - 1, y, cz, "minecraft:amethyst_block");
      if (y <= 11) {
        buildCoreBlock(cx - 2, y, cz, "minecraft:budding_amethyst");
        buildCoreBlock(cx - 1, y, cz + 1, "minecraft:amethyst_block");
        buildCoreBlock(cx - 1, y, cz - 1, "minecraft:amethyst_block");
      }
      // East Spire (cx + 1, cz)
      if (y <= 13) {
        buildCoreBlock(cx + 1, y, cz, "minecraft:smooth_quartz");
        if (y <= 10) {
          buildCoreBlock(cx + 2, y, cz, "minecraft:quartz_pillar[axis=y]");
          buildCoreBlock(cx + 1, y, cz + 1, "minecraft:smooth_quartz");
          buildCoreBlock(cx + 1, y, cz - 1, "minecraft:smooth_quartz");
        }
      }
    }
    // Golden resonance cross-bridge at y = 9
    buildCoreBlock(cx, 9, cz, "minecraft:gold_block");
    buildCoreBlock(cx, 8, cz, "minecraft:crying_obsidian");
    setBlock(cx - 1, 15, cz, "minecraft:amethyst_cluster[facing=up]");
    setBlock(cx + 1, 14, cz, "minecraft:end_rod[facing=up]");

  } else if (variant === 2) {
    // Solar Aegis Spire
    for (let y = 5; y <= 14; y++) {
      if (y <= 8) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            const isCenter = dx === 0 && dz === 0;
            buildCoreBlock(cx + dx, y, cz + dz, isCenter ? "minecraft:sea_lantern" : "minecraft:smooth_quartz");
          }
        }
        // Diagonal solar wings
        buildCoreBlock(cx - 2, y, cz - 2, "minecraft:amethyst_block");
        buildCoreBlock(cx + 2, y, cz - 2, "minecraft:amethyst_block");
        buildCoreBlock(cx - 2, y, cz + 2, "minecraft:amethyst_block");
        buildCoreBlock(cx + 2, y, cz + 2, "minecraft:amethyst_block");
      } else if (y <= 11) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            if (Math.abs(dx) + Math.abs(dz) <= 1) {
              buildCoreBlock(cx + dx, y, cz + dz, (dx === 0 && dz === 0) ? "minecraft:gold_block" : "minecraft:smooth_quartz");
            }
          }
        }
      } else if (y <= 13) {
        buildCoreBlock(cx, y, cz, "minecraft:chiseled_quartz_block");
      } else {
        buildCoreBlock(cx, y, cz, "minecraft:gold_block");
      }
    }
    setBlock(cx, 15, cz, "minecraft:lightning_rod[facing=up]");

  } else if (variant === 3) {
    // Bastion Storm Ward
    for (let y = 5; y <= 14; y++) {
      if (y <= 8) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            const isCenter = dx === 0 && dz === 0;
            buildCoreBlock(cx + dx, y, cz + dz, isCenter ? "minecraft:crying_obsidian" : "minecraft:quartz_bricks");
          }
        }
        // Raw gold veins
        buildCoreBlock(cx, y, cz - 2, "minecraft:raw_gold_block");
        buildCoreBlock(cx, y, cz + 2, "minecraft:raw_gold_block");
      } else if (y <= 11) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            if (Math.abs(dx) + Math.abs(dz) <= 1) {
              buildCoreBlock(cx + dx, y, cz + dz, "minecraft:amethyst_block");
            }
          }
        }
      } else {
        buildCoreBlock(cx, y, cz, "minecraft:crying_obsidian");
      }
    }
    setBlock(cx, 15, cz, "minecraft:amethyst_cluster[facing=up]");

  } else if (variant === 4) {
    // Astral Geode Needle
    for (let y = 5; y <= 14; y++) {
      const coreMat = (y % 2 === 0) ? "minecraft:sea_lantern" : "minecraft:crying_obsidian";
      buildCoreBlock(cx, y, cz, coreMat);

      const angle = (y - 5) * (Math.PI / 2);
      const sx = Math.round(Math.cos(angle));
      const sz = Math.round(Math.sin(angle));

      buildCoreBlock(cx + sx, y, cz + sz, "minecraft:amethyst_block");
      if (y <= 11) {
        buildCoreBlock(cx - sx, y, cz - sz, "minecraft:budding_amethyst");
      }
      if (y <= 8) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            if (!occupied.has(coordKey(cx + dx, y, cz + dz))) {
              buildCoreBlock(cx + dx, y, cz + dz, "minecraft:smooth_quartz");
            }
          }
        }
      }
    }
    setBlock(cx, 15, cz, "minecraft:end_rod[facing=up]");

  } else {
    // Prismatic Mandala Spire (8-fold symmetry)
    for (let y = 5; y <= 14; y++) {
      if (y <= 8) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            buildCoreBlock(cx + dx, y, cz + dz, (dx === 0 && dz === 0) ? "minecraft:sea_lantern" : "minecraft:amethyst_block");
          }
        }
        buildCoreBlock(cx + 2, y, cz, "minecraft:smooth_quartz");
        buildCoreBlock(cx - 2, y, cz, "minecraft:smooth_quartz");
        buildCoreBlock(cx, y, cz + 2, "minecraft:smooth_quartz");
        buildCoreBlock(cx, y, cz - 2, "minecraft:smooth_quartz");
      } else if (y <= 11) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            if (Math.abs(dx) + Math.abs(dz) <= 1) {
              buildCoreBlock(cx + dx, y, cz + dz, (dx === 0 && dz === 0) ? "minecraft:sea_lantern" : "minecraft:amethyst_block");
            } else {
              buildCoreBlock(cx + dx, y, cz + dz, "minecraft:gold_block");
            }
          }
        }
      } else {
        buildCoreBlock(cx, y, cz, "minecraft:gold_block");
      }
    }
    setBlock(cx, 15, cz, "minecraft:amethyst_cluster[facing=up]");
  }

  // --- 5. Connect Golden Tether Chains ---
  for (let i = 0; i < pylonTops.length; i++) {
    const [px, py, pz] = pylonTops[i];
    let targetX = cx;
    let targetZ = cz;
    if (variant === 1) {
      targetX = px < cx ? cx - 1 : (px > cx ? cx + 1 : cx);
    }
    const targetY = 8 + (i % 2);

    connectLine6(px, py, pz, targetX, targetY, targetZ, (lx, ly, lz, sx, sy, sz, isEnd) => {
      if (isEnd) return "minecraft:gold_block";
      if (api.random() < 0.2) return "minecraft:raw_gold_block";
      if (sy !== 0) return "minecraft:chain[axis=y]";
      if (sx !== 0) return "minecraft:chain[axis=x]";
      return "minecraft:chain[axis=z]";
    });
  }

  // --- 6. Cluster & Energy Facet Detailing ---
  const crystalBlocks = Array.from(occupied).map(k => k.split(",").map(Number));
  for (const [bx, by, bz] of crystalBlocks) {
    if (by >= 5 && by <= 13) {
      const dirs = [
        [1, 0, 0, "facing=east"],
        [-1, 0, 0, "facing=west"],
        [0, 0, 1, "facing=south"],
        [0, 0, -1, "facing=north"],
        [0, 1, 0, "facing=up"]
      ];

      for (const [dx, dy, dz, state] of dirs) {
        const nx = bx + dx;
        const ny = by + dy;
        const nz = bz + dz;

        if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
          if (!occupied.has(coordKey(nx, ny, nz))) {
            const distCenter = Math.hypot(nx - cx, nz - cz);
            if (distCenter <= 2.8 && api.random() < 0.16) {
              setBlock(nx, ny, nz, `minecraft:amethyst_cluster[${state}]`);
            }
          }
        }
      }
    }
  }

  return {
    name: "arcane_ward_crystal",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
      focus: [cx, 8, cz],
      beacon: [cx, 15, cz]
    }
  };
}
